#include <string.h>
#include <stdlib.h>

#include "magick_info.h"

size_t RegisterJPEGImage(void) {
  MagickInfo *magick_info;
  const char *version;

  version = "JPEG 1.0";

  magick_info = (MagickInfo *) malloc(sizeof(*magick_info));
  if (magick_info == NULL) {
    return 0;
  }

  (void) memset(magick_info, 0, sizeof(*magick_info));

  magick_info->name = ConstantString("JPE");
  magick_info->description = ConstantString("JPEG image format");
  magick_info->decoder = JPEGDecoder;
  magick_info->encoder = JPEGEcoder;
  magick_info->thread_support = MagickFalse;
  magick_info->mime_type = ConstantString("image/jpeg");

  if (JPEGLibrarySupportsThreads()) {
    magick_info->thread_support = MagickTrue;
  }

  if (RegisterMagickInfo(magick_info) != MagickFalse) {
    magick_info = (MagickInfo *) malloc(sizeof(*magick_info));
    if (magick_info == NULL) {
      return 0;
    }

    (void) memset(magick_info, 0, sizeof(*magick_info));

    magick_info->name = ConstantString("JPEG");
    magick_info->description = ConstantString("JPEG image format");
    magick_info->decoder = JPEGDecoder;
    magick_info->encoder = JPEGEcoder;
    magick_info->thread_support = MagickFalse;
    magick_info->mime_type = ConstantString("image/jpeg");

    if (JPEGLibrarySupportsThreads()) {
      magick_info->thread_support = MagickTrue;
    }

    if (RegisterMagickInfo(magick_info) != MagickFalse) {
      magick_info = (MagickInfo *) malloc(sizeof(*magick_info));
      if (magick_info == NULL) {
        return 0;
      }

      (void) memset(magick_info, 0, sizeof(*magick_info));

      magick_info->name = ConstantString("JPG");
      magick_info->description = ConstantString("JPEG image format");
      magick_info->decoder = JPEGDecoder;
      magick_info->encoder = JPEGEcoder;
      magick_info->thread_support = MagickFalse;
      magick_info->mime_type = ConstantString("image/jpeg");

      if (JPEGLibrarySupportsThreads()) {
        magick_info->thread_support = MagickTrue;
      }

      if (RegisterMagickInfo(magick_info) != MagickFalse) {
        magick_info = (MagickInfo *) malloc(sizeof(*magick_info));
        if (magick_info == NULL) {
          return 0;
        }

        (void) memset(magick_info, 0, sizeof(*magick_info));

        magick_info->name = ConstantString("JPS");
        magick_info->description = ConstantString("JPEG image format");
        magick_info->decoder = JPEGDecoder;
        magick_info->encoder = JPEGEcoder;
        magick_info->thread_support = MagickFalse;
        magick_info->mime_type = ConstantString("image/jpeg");

        if (JPEGLibrarySupportsThreads()) {
          magick_info->thread_support = MagickTrue;
        }

        if (RegisterMagickInfo(magick_info) != MagickFalse) {
          magick_info = (MagickInfo *) malloc(sizeof(*magick_info));
          if (magick_info == NULL) {
            return 0;
          }

          (void) memset(magick_info, 0, sizeof(*magick_info));

          magick_info->name = ConstantString("PJPEG");
          magick_info->description = ConstantString("JPEG image format");
          magick_info->decoder = JPEGDecoder;
          magick_info->encoder = JPEGEcoder;
          magick_info->thread_support = MagickFalse;
          magick_info->mime_type = ConstantString("image/jpeg");

          if (JPEGLibrarySupportsThreads()) {
            magick_info->thread_support = MagickTrue;
          }

          if (RegisterMagickInfo(magick_info) != MagickFalse) {
            return sizeof(*magick_info);
          }
        }
      }
    }
  }

  free(magick_info);
  return 0;
}
